func (p *DeviceConfigPoller) PollMetrics(device *Device) error {
    oids := []string{
        ".1.3.6.1.2.1.1.1.0",    // SystemDescription
        ".1.3.6.1.2.1.1.2.0",    // SystemOID
        ".1.3.6.1.6.3.10.2.1.3.0", // StartedTimeSeconds - PROBLEMATIC
        ".1.3.6.1.2.1.1.3.0",    // StartedTime
        ".1.3.6.1.2.1.1.5.0",    // ObjectName
        ".1.3.6.1.2.1.1.6.0",    // SystemLocation
    }
    result, err := p.snmpClient.GetBulk(oids)
    if err != nil {
        return fmt.Errorf("SNMP bulk get failed: %v", err)
    }
    return p.processResults(result)
}

func (c *Client) GetBulk(oids []string) (map[string]interface{}, error) {
    pdu := gosnmp.SnmpPDU{Name: oids[0], Type: gosnmp.OctetString}
    for _, oid := range oids[1:] {
        pdu.Name = oid
    }
    result, err := c.conn.GetBulk(oids, 0, uint8(len(oids)))
    if err != nil {
        return nil, err // No fallback - fails entirely
    }
    return c.parseResponse(result), nil
}

