public class SystemProcess {
    private static final Logger logger = LoggerFactory.getLogger(SystemProcess.class);

    public ThreadDumpInfo generateThreadDump() {
        ThreadMXBean threadMX = ManagementFactory.getThreadMXBean();
        ThreadInfo[] threadInfos = threadMX.dumpAllThreads(true, true);
        return new ThreadDumpInfo(threadInfos);
    }

    public HeapDumpInfo generateHeapDump(String filePath) {
        try {
            HotSpotDiagnosticMXBean mxBean = ManagementFactory.newPlatformMXBeanProxy(
                ManagementFactory.getPlatformMBeanServer(),
                "com.sun.management:type=HotSpotDiagnostic", HotSpotDiagnosticMXBean.class);
            mxBean.dumpHeap(filePath, true);
            return new HeapDumpInfo(filePath, new File(filePath).length());
        } catch (Exception e) {
            logger.error("Failed to generate heap dump", e);
            return null;
        }
    }
}

