public class RemoteEventChangeNotificationHandler {
    private NotificationService notificationService;
    private EmailTemplateEngine templateEngine;

    public void handleEvent(AlertEvent event) {
        if (shouldNotify(event)) {
            String message = templateEngine.processTemplate(event);
            notificationService.sendNotification(message, event.getUsers());
        }
    }

    private boolean shouldNotify(AlertEvent event) {
        return !event.isAcknowledged() && event.getSeverity() != Severity.CLEAR;
    }
}

public class EmailTemplateEngine {
    public String processTemplate(AlertEvent event) {
        String template = getDefaultTemplate();
        // Basic string replacement
        template = template.replace("${alertName}", event.getAlertName());
        template = template.replace("${severity}", event.getSeverity().toString());
        return template;
    }

    private String getDefaultTemplate() {
        return "Alert: ${alertName} - Severity: ${severity}";
    }
}

public class MacroProcessor {
    private Map<String, MacroResolver> resolvers = new HashMap<>();

    public MacroProcessor() {
        // Currently only basic macros
        resolvers.put("$$$object.name$$$", new ObjectNameResolver());
        resolvers.put("$$$severity$$$", new SeverityResolver());
    }

    public String processMacros(String template, AlertEvent event) {
        String result = template;
        for (Map.Entry<String, MacroResolver> entry : resolvers.entrySet()) {
            result = result.replace(entry.getKey(), entry.getValue().resolve(event));
        }
        return result;
    }
}

