public class TrapCacheStore {
    private ConcurrentMap<String, Byte> acknowledgements = new ConcurrentHashMap<>();

    public void acknowledgeEvent(String eventSource, String trapOid) {
        String key = eventSource + trapOid;
        acknowledgements.put(key, (byte) 1);
    }

    public void resetAcknowledgement(String eventSource, String trapOid) {
        String key = eventSource + trapOid;
        acknowledgements.put(key, (byte) 0);
    }

    public boolean isAcknowledged(String eventSource, String trapOid) {
        String key = eventSource + trapOid;
        return acknowledgements.getOrDefault(key, (byte) 0) == 1;
    }
}

public class EventSender {
    private TrapCacheStore trapCache;

    public void processAlert(AlertEvent event) {
        if (event.getType().equals("TRAP")) {
            // Only trap events use acknowledgement
            trapCache.resetAcknowledgement(event.getSource(), event.getOid());
        }
        sendToUI(event);
    }

    public void acknowledgeAlert(String source, String oid, String alertType) {
        if (alertType.equals("TRAP")) {
            trapCache.acknowledgeEvent(source, oid);
        }
        // LOG and FLOW alerts are ignored
    }
}

