public class AlertStateManager {
  private Map<String, AlertState> deviceStates = new HashMap<>();

  public boolean shouldForwardAlert(Alert alert) {
    String deviceId = alert.getDeviceId();
    AlertState currentState = deviceStates.get(deviceId);

    if (currentState == null || currentState != alert.getSeverity()) {
      deviceStates.put(deviceId, AlertState.from(alert.getSeverity()));
      return true;
    }
    return false; // Don't forward duplicate states
  }

  public void markCleared(String deviceId) {
    deviceStates.put(deviceId, AlertState.CLEARED);
  }
}

