public class InterfaceRediscoveryScheduler {
    public void rediscoverInterfaces() {
        List<NetworkDevice> devices = getNetworkDevices();
        for (NetworkDevice device : devices) {
            InterfaceData newData = discoverInterfaceData(device);
            updateInterfaceMetrics(device, newData);
        }
    }

    private void updateInterfaceMetrics(NetworkDevice device, InterfaceData data) {
        InterfaceMetricSettings settings = device.getInterfaceMetricSettings();

        // FIXED: Preserve configured speed if it exists
        if (settings.hasConfiguredSpeed()) {
            // Keep the manually configured speed
            Long configuredSpeed = settings.getConfiguredSpeed();
            settings.setDiscoveredSpeed(data.getDiscoveredSpeed());
            settings.setConfiguredSpeed(configuredSpeed); // Preserve configured value
            device.setInterfaceSpeed(configuredSpeed);
        } else {
            // Use discovered speed if no manual configuration
            settings.setDiscoveredSpeed(data.getDiscoveredSpeed());
            device.setInterfaceSpeed(data.getDiscoveredSpeed());
        }
    }
}

