public class HealthUtil {
    private static final double DISK_CRITICAL_THRESHOLD = 0.90;
    private static final double DISK_MAJOR_THRESHOLD = 0.85;
    private static final double DISK_WARNING_THRESHOLD = 0.80;

    public void checkDiskUtilization() {
        double currentDirUsage = getCurrentDirectoryUsage();
        double rootDirUsage = getRootDirectoryUsage();

        if (currentDirUsage >= DISK_CRITICAL_THRESHOLD || rootDirUsage >= DISK_CRITICAL_THRESHOLD) {
            logger.error("Disk usage critical. Stopping motadata service.");
            stopMotadataService();
        } else if (currentDirUsage > DISK_MAJOR_THRESHOLD || rootDirUsage > DISK_MAJOR_THRESHOLD) {
            logger.error("Disk usage major alert", Severity.MAJOR);
        } else if (currentDirUsage > DISK_WARNING_THRESHOLD || rootDirUsage > DISK_WARNING_THRESHOLD) {
            logger.warn("Disk usage warning", Severity.WARNING);
        }
    }

    public void clearCacheOnHealthAgentRestart() {
        if (!isNormalAgent()) {
            clearCacheFolder();
        }
    }
}

