public class NetRoutePolicyInspector {
  private List<PolicyEvent> events = new ArrayList<>();

  public void inspectPolicy(PolicyEvent event) {
    events.add(event);
    insertionSort(events); // Sorting on every insertion!
  }

  private void insertionSort(List<PolicyEvent> list) {
    for (int i = 1; i < list.size(); i++) {
      PolicyEvent key = list.get(i);
      int j = i - 1;
      while (j >= 0 && list.get(j).getPriority() > key.getPriority()) {
        list.set(j + 1, list.get(j));
        j--;
      }
      list.set(j + 1, key);
    }
  }
}

