private static ScheduledExecutorService logLevelResetTimer;
private static final String LOG_LEVEL_RESET_TIME_CONFIG = "log.level.reset.minutes";

private static void setupLogging() {
    String currentLevel = getCurrentLogLevel();
    if ("DEBUG".equalsIgnoreCase(currentLevel) || "TRACE".equalsIgnoreCase(currentLevel)) {
        scheduleLogLevelReset();
    }
}

private static void scheduleLogLevelReset() {
    int resetTimeMinutes = getConfigProperty(LOG_LEVEL_RESET_TIME_CONFIG, 30);
    logLevelResetTimer = Executors.newSingleThreadScheduledExecutor();

    logLevelResetTimer.schedule(() -> {
        setLogLevel("INFO");
        logger.info("Log level automatically reset to INFO after {} minutes", resetTimeMinutes);
    }, resetTimeMinutes, TimeUnit.MINUTES);
}
