public class CustomMonitoringField {
  private String oidValue;

  public boolean validateOid(String oid) {
    if (oid == null || oid.trim().isEmpty()) {
      throw new IllegalArgumentException("Invalid SNMP OID value");
    }
    // Basic OID format check
    return oid.matches("^\\d+(\\.\\d+)*$");
  }
}

