public class PingUtil {
    private static final Logger logger = LoggerFactory.getLogger(PingUtil.class);

    public boolean pingDevice(String ip) {
        NuProcessBuilder pb = new NuProcessBuilder("fping", "-c", "1", "-t", "1000", "-q", "-u", ip);
        NuProcess process = pb.start();
        // Process spawning issues with long running operations
        return process.waitFor(2000, TimeUnit.MILLISECONDS);
    }
}

