public class TagNormalizer {
  public void normalizeObjectTags() {
    // Convert old uppercase tags to lowercase
    String sql = "UPDATE objects SET tags = LOWER(tags) WHERE tags REGEXP '[A-Z]'";
    executeUpdate(sql);
  }

  public void normalizeInstanceTags() {
    String sql = "UPDATE instances SET tags = LOWER(tags) WHERE tags REGEXP '[A-Z]'";
    executeUpdate(sql);
  }
}

public class DataMigration {
  @Override
  public void migrate() {
    TagNormalizer normalizer = new TagNormalizer();
    normalizer.normalizeObjectTags();
    normalizer.normalizeInstanceTags();
    logger.info("Tag normalization completed");
  }
}

