public class SNMPMetricsProcessor {
  public Map<String, Object> processScalarMetrics(List<String> oids) {
    Map<String, Object> result = new HashMap<>();
    Map<String, String> validOids = new HashMap<>();

    for (String oid : oids) {
      if (isValidOid(oid)) {
        validOids.put(oid, "valid");
      }
    }

    // BUG: For scalar metrics, valid.oids map is included in result
    result.put("valid.oids", validOids);
    return result;
  }
}

