public class NetRoutePolicyInspector {
    private Map<String, PolicyState> triggeredPolicy = new ConcurrentHashMap<>();

    public void processAvailabilityMetric(MetricData metric) {
        String policyKey = generatePolicyKey(metric);
        if ("Down".equals(metric.getStatus()) && !triggeredPolicy.containsKey(policyKey)) {
            // Only process if not already triggered
            processPolicyFlap(metric);
            triggeredPolicy.put(policyKey, new PolicyState());
        }
    }
}
